    #[doc = " Query an AABB for the closest object. The callback function is called for each proxy that might be closest to the supplied\n point.\n @param tree the dynamic tree to query\n @param point the query point\n @param maskBits proxies are skipped if the bit-wise AND with the proxy category bits is zero\n @param requireAllBits proxies are skipped if the bit-wise AND with the proxy category bits does not equal the maskBits\n @param callback a user provided instance of b3TreeQueryClosestCallbackFcn\n @param context a user context object that is provided to the callback\n @param minDistanceSqr the initial and final minimum squared distance. Provide a small initial to restrict the search and\n improve performance. If the value is large this query has performance that scales linearly with the number of proxies and\n would be slower than a brute force search.\n\t@return performance data"]
    pub fn b3DynamicTree_QueryClosest(
        tree: *const b3DynamicTree,
        point: b3Vec3,
        maskBits: u64,
        requireAllBits: bool,
        callback: b3TreeQueryClosestCallbackFcn,
        context: *mut ::core::ffi::c_void,
        minDistanceSqr: *mut f32,
    ) -> b3TreeStats;
    #[doc = " Ray cast against the proxies in the tree. This relies on the callback\n to perform an exact ray cast in the case where the proxy contains a shape.\n The callback also performs any collision filtering. This has performance\n roughly equal to k * log(n), where k is the number of collisions and n is the\n number of proxies in the tree.\n Bit-wise filtering using mask bits can greatly improve performance in some scenarios.\n\tHowever, this filtering may be approximate, so the user should still apply filtering to results.\n @param tree the dynamic tree to ray cast\n @param input the ray cast input data. The ray extends from p1 to p1 + maxFraction * (p2 - p1)\n @param maskBits bit mask test: `bool accept = (maskBits & proxy->categoryBits) != 0;`\n @param requireAllBits modifies bit mask test: `bool accept = (maskBits & proxy->categoryBits) == maskBits;`\n @param callback a callback function that is called for each proxy that is hit by the ray\n @param context user context that is passed to the callback\n\t@return performance data"]
    pub fn b3DynamicTree_RayCast(
        tree: *const b3DynamicTree,
        input: *const b3RayCastInput,
        maskBits: u64,
        requireAllBits: bool,
        callback: b3TreeRayCastCallbackFcn,
        context: *mut ::core::ffi::c_void,
    ) -> b3TreeStats;
    #[doc = " Sweep an AABB through the tree. The box is in the tree's world float frame and the callback\n re-differences each shape at full precision against the query origin. Used by the large world\n spatial queries so the tree traversal stays float while the narrow phase stays precise."]
    pub fn b3DynamicTree_BoxCast(
        tree: *const b3DynamicTree,
        input: *const b3BoxCastInput,
        maskBits: u64,
        requireAllBits: bool,
        callback: b3TreeBoxCastCallbackFcn,
        context: *mut ::core::ffi::c_void,
    ) -> b3TreeStats;
